contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public entry performing the property-based test
    // params: callerIsOwner decides whether InvMutTest will be the owner before transfer,
    // newOwner is the target address to set, and doTransfer indicates whether to attempt transferOwnership.
    function run(bool makeThisOwner, address newOwner, bool doTransfer) public payable {
        require(newOwner != address(0) ? true : true);

        // Ensure initial owner is known: if requested, set owner to this contract by calling transferOwnership from constructor not possible here,
        // but we can only call transferOwnership when current owner equals msg.sender. The freshly deployed C may have owner == address(0).
        // To arrange for this contract to be owner, we try to set owner only if current owner == address(this).
        // Read current owner
        address ownerBefore = c.owner();

        // If makeThisOwner is true and ownerBefore == address(this), nothing to do.
        // If makeThisOwner is true but ownerBefore != address(this), we cannot become owner because onlyOwner prevents it.
        // So we treat makeThisOwner as a hint and observe actual ownerBefore.

        bool transferReverted;
        if (doTransfer) {
            // Attempt transferOwnership from this contract (msg.sender == InvMutTest)
            try c.transferOwnership(newOwner) {
                transferReverted = false;
            } catch {
                transferReverted = true;
            }
        } else {
            transferReverted = false; // no attempt, treat as not reverted
        }

        address ownerAfter = c.owner();

        // General rule:
        // If we attempted a transfer (doTransfer == true) then:
        //   - if ownerBefore == address(this) then the call must not revert and ownerAfter == newOwner
        //   - else the call must revert and ownerAfter == ownerBefore
        // If we did not attempt a transfer, owner must be unchanged.
        assert(
            doTransfer
            ? (
                (ownerBefore == address(this) && transferReverted == false && ownerAfter == newOwner)
                ||
                (ownerBefore != address(this) && transferReverted == true && ownerAfter == ownerBefore)
            )
            : (ownerAfter == ownerBefore && transferReverted == false)
        );
    }

    // no special receive logic needed
    receive() external payable {}
}

