            c.transferOwnership(possibleOwner);
            changed = true;
        } else {
            // we are not owner; attempt to change ownership to newOwner will revert. We do not require success.
            bool didRevert;
            try c.transferOwnership(newOwner) {
                didRevert = false;
            } catch {
                didRevert = true;
            }
            // ignore outcome; proceed to the core check
        }

        // Read owner after any setup
        address ownerAfter = c.owner();

        // Attempt to call owned(); record whether it reverted. owned() has onlyOwner modifier, so it should succeed iff msg.sender==owner
        bool ownedReverted;
        try c.owned() {
            ownedReverted = false;
        } catch {
            ownedReverted = true;
        }

        // General rule: owned() does not mutate owner, and it succeeds exactly when this contract is the current owner.
        assert((ownedReverted == (ownerAfter != address(this))) && ownerAfter == c.owner());
    }

    receive() external payable { }
